class Solution { public:
 int countSubMultisets(vector<int>& nums,int l,int r){
  const int MOD=1000000007;unordered_map<int,int> freq;for(int x:nums)++freq[x];
  vector<int> dp(r+1);dp[0]=1;
  for(auto p:freq){int x=p.first,c=p.second;if(x==0){for(int &v:dp)v=(long long)v*(c+1)%MOD;continue;}
   vector<int> ndp(r+1);
   for(int rem=0;rem<x && rem<=r;++rem){long long window=0;int idx=0;
    for(int s=rem;s<=r;s+=x,++idx){window+=dp[s];if(idx>c)window-=dp[s-(c+1)*x];window=(window%MOD+MOD)%MOD;ndp[s]=(int)window;}}
   dp.swap(ndp);
  }
  int ans=0;for(int s=l;s<=r;++s)ans=(ans+dp[s])%MOD;return ans;
 }
};
